toolInput.old_string:
// Orcha Agents fork: use a separate data directory to avoid conflict with official Craft Agents.
// CRAFT_CONFIG_DIR controls where config.json, credentials, workspaces etc. live.
// CRAFT_USER_DATA_DIR controls Electron's userData (window state, caches, etc.)
// Both must be set before requestSingleInstanceLock() which uses the userData path.
const ORCHA_DATA_DIR = join(homedir(), '.orcha-agents')
if (!process.env.CRAFT_CONFIG_DIR) {
  process.env.CRAFT_CONFIG_DIR = ORCHA_DATA_DIR
}
if (app.isPackaged && !process.env.CRAFT_USER_DATA_DIR) {
  app.setPath('userData', join(ORCHA_DATA_DIR, 'electron-data'))
}
if (process.env.CRAFT_USER_DATA_DIR) {
  app.setPath('userData', process.env.CRAFT_USER_DATA_DIR)
}

toolInput.new_string:
// Orcha Agents fork: userData path for Electron (window state, caches).
// CRAFT_CONFIG_DIR is already set at the top of this file (before all imports).
if (app.isPackaged && !process.env.CRAFT_USER_DATA_DIR) {
  app.setPath('userData', ORCHA_DATA_DIR + '/electron-data')
}
if (process.env.CRAFT_USER_DATA_DIR) {
